tools.example:
f = figure('Name', 'Results', 'NumberTitle', 'off', ...
           'Position', [100 100 800 500], 'Color', 'w');
plot(1:10, rand(1,10))
fInvisible = figure('Visible', 'off');
plot(1:10, rand(1,10));
exportgraphics(fInvisible, 'plot.png');
close(fInvisible);

figure
main = axes('Position', [0.1 0.1 0.85 0.8]);
plot(main, linspace(0,10,200), sin(linspace(0,10,200)))
inset = axes('Position', [0.6 0.6 0.25 0.25]);
plot(inset, linspace(0,1,50), sin(linspace(0,1,50)))
box(inset, 'on')

figure
subplot(2, 2, 1); plot(rand(1,10)); title('a')
subplot(2, 2, 2); histogram(randn(1,500)); title('b')
subplot(2, 2, [3 4]); plot(cumsum(randn(1,200))); title('c')
ax = subplot(2,2,1);
ax.YLim = [0 1];

tiledlayout(3, 3, 'TileSpacing', 'tight');
ax1 = nexttile([2 2]);
imagesc(peaks(40)); axis image off
nexttile(3); plot(rand(1,10))
nexttile(6); plot(rand(1,10))
nexttile(7, [1 3]); plot(cumsum(randn(1,100)))

semilogx(logspace(-1, 3, 200), rand(1, 200))
grid on
grid minor
ax = gca;
ax.GridAlpha = 0.3;
ax.YGrid = 'off';

tiledlayout(2,1)
ax1 = nexttile; plot(randn(1,100));
ax2 = nexttile; plot(2*randn(1,100));
linkaxes([ax1 ax2], 'y')
ylim(ax1, [-6 6])
yl = ylim(ax2)

bar([3 7 5 9])
xticks(1:4)
xticklabels({'North','South','East','West'})
xtickangle(45)
ax = gca;
ax.TickLabelInterpreter = 'latex';

plot(linspace(0,10,100), rand(1,100))
xlabel('time (s)', 'FontSize', 12)
ylabel('$v$ (m s$^{-1}$)', 'Interpreter', 'latex', 'FontSize', 12)
t = xlabel('time');
t.Color = [0.3 0.3 0.3];

plot(1:10, rand(1,10))
title('Sensor response', 'gain = 2.5, filtered')
title({'Line one'; 'Line two'})
title(sprintf('RMSE = %.3f', 0.0421), 'FontSize', 14)
[t, s] = title('main', 'sub');
s.FontAngle = 'italic';

x = linspace(0, 10, 100);
plot(x, sin(x), 'DisplayName', 'sin')
hold on
plot(x, cos(x), 'DisplayName', 'cos')
plot(x, zeros(size(x)), 'HandleVisibility', 'off')
hold off
lgd = legend('Location', 'northeastoutside');
lgd.Title.String = 'series';

imagesc(peaks(50))
colormap(turbo)
c = colorbar('eastoutside');
c.Label.String = 'amplitude (V)';
c.Ticks = -8:4:8;
clim([-8 8])

[X, Y] = meshgrid(linspace(-3,3,80));
s = surf(X, Y, peaks(X, Y));
s.EdgeColor = 'none';
lgt = camlight('headlight');
lighting gouraud
material dull
view(-40, 35)
camlight(lgt, 'right')

[X, Y] = meshgrid(linspace(-3,3,40));
Z = peaks(X, Y);
tiledlayout(1,3)
nexttile; surf(X,Y,Z); shading faceted; title('faceted')
nexttile; surf(X,Y,Z); shading flat; title('flat')
nexttile; surf(X,Y,Z); shading interp; title('interp')

h = plot(1:10, rand(1,10));
get(h, 'Color')
S = get(gca);
S.XLim
h.LineWidth
hs = plot(rand(5,3));
get(hs, 'Color')

plot(1:10, rand(1,10))
ax = gca;
ax.FontSize = 12;
ax.XGrid = 'on';
ax.TickDir = 'out';
ax.YColor = [0.3 0.3 0.3];
cla(ax)

plot(1:10, rand(1,10))
fig = gcf;
fig.Position = [100 100 900 500];
fig.Color = 'w';
exportgraphics(fig, 'plot.pdf', 'ContentType', 'vector');
close(fig)

plot(1:10, rand(1,10), 'Tag', 'data')
hold on; plot(1:10, 0.5*ones(1,10), 'Tag', 'ref'); hold off
h = findobj(gcf, 'Tag', 'ref');
h.Color = 'r';
allLines = findobj(gcf, 'Type', 'line');
numel(allLines)
set(findall(gcf, '-property', 'FontSize'), 'FontSize', 12)

fig = openfig('result.fig', 'invisible');
lines = findobj(fig, 'Type', 'line');
x = lines(1).XData;
y = lines(1).YData;
exportgraphics(fig, 'result.png', 'Resolution', 300);
close(fig)

for k = 1:3
    f = figure('Visible', 'off');
    plot(rand(1,10));
    exportgraphics(f, sprintf('f%d.png', k));
    close(f);
end
close all
close all hidden

